import 'package:flutter/cupertino.dart';

import 'isar/models/contact_entry.dart';
import '../wallets/crypto_currency/crypto_currency.dart';

class AddressEntryData extends ChangeNotifier {
  late int id;

  AddressEntryData(this.id);

  String? _address;
  CryptoCurrency? _coin;

  String? get address => _address;

  set address(String? address) {
    _address = address;
    notifyListeners();
  }

  CryptoCurrency? get coin => _coin;

  set coin(CryptoCurrency? coin) {
    _coin = coin;
    notifyListeners();
  }

  bool get isEmpty {
    if (address != null && address!.isNotEmpty) {
      return false;
    }
    if (coin != null) {
      return false;
    }
    return true;
  }

  bool get isValid {
    if (_address == null || coin == null || _address!.isEmpty) {
      return false;
    }
    return isValidAddress;
  }

  /// The address belongs to a known coin (the form sets [coin] from it).
  bool get isValidAddress {
    if (_address == null || coin == null) {
      return false;
    }
    return _coin!.validateAddress(_address!);
  }

  ContactAddressEntry buildAddressEntry() {
    return ContactAddressEntry()
      ..coinName = coin!.identifier
      ..address = address!;
  }

  @override
  String toString() {
    return "AddressEntryData: { address: $address, coin: ${coin?.identifier} }";
  }
}
